const emptyStats = {
  summary: { totalFees: 0, totalTurnover: 0, totalTrades: 0, averageFee: 0 }
};
const [revenueStats, setRevenueStats] = useState({
  today: emptyStats,
  week: emptyStats,
  month: emptyStats,
  year: emptyStats,
  allTime: { totalRevenue: 0, totalTurnover: 0, totalTrades: 0 },
  topUsers: []
});
